19	
20	// TestServeOwnerHandoverRecoversAcrossKill exercises the full
21	// request -> durable record -> restart path for a legal handover. The
22	// recovered detail view must show the last owner, an unchanged membership
23	// sorted by name, versions and history matching the successful actions one
24	// for one, and the saved operator/target/timestamp on the handover entry.
25	// Names differing only in case stay distinct end to end.
26	func TestServeOwnerHandoverRecoversAcrossKill(t *testing.T) {
27		dataDir := t.TempDir()
28		p := startServer(t, dataDir)
29	
30		if status, created := postIncident(t, p, `{"id":"INC-7","title":"Outage","service":"gateway","operator":"Alice"}`); status != http.StatusOK || incNumber(created["version"]) != 1 {
31			t.Fatalf("create %d %v", status, created)
32		}
33		addLower := `{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`
34		if status, add := postIncidentAction(t, p, "INC-7", addLower); status != http.StatusOK || incNumber(add["version"]) != 2 {
35			t.Fatalf("add bob %d %v", status, add)
36		}
37		addUpper := `{"action_id":"p2","operator":"alice","expected_version":2,"action":"add_participant","participant":"Bob"}`
38		if status, add := postIncidentAction(t, p, "INC-7", addUpper); status != http.StatusOK || incNumber(add["version"]) != 3 {
39			t.Fatalf("add Bob %d %v", status, add)
40		}
41		assignUpper := `{"action_id":"o1","operator":"alice","expected_version":3,"action":"assign_owner","participant":"Bob"}`
42		if status, assign := postIncidentAction(t, p, "INC-7", assignUpper); status != http.StatusOK || incNumber(assign["version"]) != 4 {
43			t.Fatalf("assign Bob %d %v", status, assign)
44		}
45	
46		status, before := getIncident(t, p, "INC-7")
47		if status != http.StatusOK {
48			t.Fatalf("get before restart %d", status)
49		}
50		members, _ := before["participants"].([]any)
51		if len(members) != 3 || members[0] != "Alice" || members[1] != "Bob" || members[2] != "bob" {
52			t.Fatalf("participants sorted, case kept: %v", before["participants"])
53		}
54		if before["owner"] != "Bob" || before["status"] != "open" || incNumber(before["version"]) != 4 {
55			t.Fatalf("head before restart: %v", before)
56		}
57		histBefore, _ := before["history"].([]any)
58		lastBefore := histBefore[3].(map[string]any)
59		if lastBefore["action"] != "assign_owner" || lastBefore["action_id"] != "o1" ||
60			lastBefore["operator"] != "alice" || lastBefore["content"] != "Bob" ||
61			incNumber(lastBefore["version"]) != 4 || lastBefore["at"] == nil || lastBefore["at"] == "" {
62			t.Fatalf("handover history entry before restart: %v", lastBefore)
63		}
64		savedAt := lastBefore["at"].(string)
65	
66		// Hard kill; confirmed records are the only source on the next start.
67		p.signal(t, syscall.SIGKILL)
68		p.waitExit(t, -1)
69		waitTCPPortClosed(t, p.addr)
70	
71		p2 := startServer(t, dataDir)
72		status, got := getIncident(t, p2, "INC-7")
73		if status != http.StatusOK {
74			t.Fatalf("get after restart %d", status)
75		}
76		if got["status"] != "open" || incNumber(got["version"]) != 4 {
77			t.Fatalf("recovered status/version: %v", got)
78		}
79		if got["owner"] != "Bob" {
80			t.Fatalf("recovered owner %v", got["owner"])
81		}
82		recovered, _ := got["participants"].([]any)
83		if len(recovered) != 3 || recovered[0] != "Alice" || recovered[1] != "Bob" || recovered[2] != "bob" {
84			t.Fatalf("handover must leave both case variants participating: %v", got["participants"])
85		}
86	
87		history, _ := got["history"].([]any)
88		if len(history) != 4 {
89			t.Fatalf("history must line up 1:1 with the four successful actions, got %d", len(history))
90		}
91		wantActions := []struct {
92			actionID any
93			operator string
94			action   string
95			content  string
96			version  int
97		}{
98			{nil, "Alice", "create", "Outage", 1},
99			{"p1", "alice", "add_participant", "bob", 2},
100			{"p2", "alice", "add_participant", "Bob", 3},
101			{"o1", "alice", "assign_owner", "Bob", 4},
102		}
103		for i, w := range wantActions {
104			entry := history[i].(map[string]any)
105			if entry["action_id"] != w.actionID || entry["operator"] != w.operator ||
106				entry["action"] != w.action || entry["content"] != w.content ||
107				incNumber(entry["version"]) != w.version {
108				t.Fatalf("history[%d] %v want %+v", i, entry, w)
109			}
110			if entry["at"] == nil || entry["at"] == "" {
111				t.Fatalf("history[%d] missing saved timestamp", i)
112			}
113		}
114		// The handover entry keeps the exact server timestamp captured before the
115		// kill, not a recovery-time value.
116		if history[3].(map[string]any)["at"] != savedAt {
117			t.Fatalf("handover timestamp changed across restart: %v vs %s", history[3], savedAt)
118		}
119	
120		// Idempotent retries after restart return first results; a handover retry
121		// must not be counted as another successful action.
122		if s, r := postIncidentAction(t, p2, "INC-7", addLower); s != http.StatusOK || incNumber(r["version"]) != 2 {
123			t.Fatalf("add retry %d %v", s, r)
124		}
125		if s, r := postIncidentAction(t, p2, "INC-7", assignUpper); s != http.StatusOK || incNumber(r["version"]) != 4 {
126			t.Fatalf("assign retry %d %v", s, r)
127		}
128		if _, still := getIncident(t, p2, "INC-7"); incNumber(still["version"]) != 4 {
129			t.Fatalf("retries must not advance version: %v", still["version"])
130		}
131	
132		p2.signal(t, syscall.SIGTERM)
133		p2.waitExit(t, 0)
134	}
135	
136	// TestServeFailsOnIllegalHandoverRecordWithoutMutation covers the regression
137	// where the request entry refuses a handover but recovery accepts the same
138	// kind of record. Each injected record is a complete, CRC-valid frame with
139	// legal fields, a timestamp, a sequential expected_version, and a fresh
140	// action_id, so the failure must come from the handover rule: it must abort
141	// startup (non-zero exit, no readiness line), name why the target is illegal,
142	// and leave every saved byte — including the complete offending frame — in
143	// place rather than trimming it as a torn tail or auto-joining/substituting.
144	func TestServeFailsOnIllegalHandoverRecordWithoutMutation(t *testing.T) {
145		stamp := func(sec int) time.Time {
146			return time.Date(2026, 10, 1, 12, 0, 0, sec, time.UTC)
147		}
148		frame := func(t *testing.T, record incidents.Record) []byte {
149			t.Helper()
150			payload, err := incidents.MarshalRecord(record)
151			if err != nil {
152				t.Fatal(err)
153			}
154			out := make([]byte, 8+len(payload))
155			binary.BigEndian.PutUint32(out[0:4], uint32(len(payload)))
156			binary.BigEndian.PutUint32(out[4:8], crc32.ChecksumIEEE(payload))
157			copy(out[8:], payload)
158			return out
159		}
160		appendFrames := func(t *testing.T, path string, records ...incidents.Record) []byte {
161			t.Helper()
162			existing, err := os.ReadFile(path)
163			if err != nil {
164				t.Fatal(err)
165			}
166			content := append([]byte{}, existing...)
167			for _, record := range records {
168				content = append(content, frame(t, record)...)
169			}
170			if err := os.WriteFile(path, content, 0o644); err != nil {
171				t.Fatal(err)
172			}
173			return content
174		}
175	
176		t.Run("handover to a never-joined participant at the tail", func(t *testing.T) {
177			dataDir := t.TempDir()
178			first := startServer(t, dataDir)
179			postIncident(t, first, `{"id":"INC-8","title":"t","service":"gateway","operator":"Alice"}`)
180			if s, _ := postIncidentAction(t, first, "INC-8",
181				`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
182				t.Fatalf("add bob status %d", s)
183			}
184			first.signal(t, syscall.SIGKILL)
185			first.waitExit(t, -1)
186			waitTCPPortClosed(t, first.addr)
187	
188			// Complete, well-formed record: fresh action id, sequential version,
189			// legal in every respect except that carol never joined.
190			bad := incidents.NewActionRecord(incidents.Request{
191				IncidentID: "INC-8", ActionID: "o1", Operator: "alice",
192				ExpectedVersion: 2, Type: incidents.ActionAssignOwner, Content: "carol",
193			}, stamp(1))
194			path := filepath.Join(dataDir, "incidents.log")
195			wantBytes := appendFrames(t, path, bad)
196	
197			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
198				"recover incidents", "non-participant", `"carol"`)
199	
200			// A later start still fails the same way: the complete bad frame was
201			// neither discarded as a torn tail nor replaced by a default owner.
202			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
203				"recover incidents", "non-participant", `"carol"`)
204		})
205	
206		t.Run("self-handover ahead of another legal record", func(t *testing.T) {
207			dataDir := t.TempDir()
208			first := startServer(t, dataDir)
209			postIncident(t, first, `{"id":"INC-8","title":"t","service":"gateway","operator":"Alice"}`)
210			if s, _ := postIncidentAction(t, first, "INC-8",
211				`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
212				t.Fatalf("add bob status %d", s)
213			}
214			if s, _ := postIncidentAction(t, first, "INC-8",
215				`{"action_id":"o0","operator":"alice","expected_version":2,"action":"assign_owner","participant":"bob"}`); s != http.StatusOK {
216				t.Fatalf("assign bob status %d", s)
217			}
218			first.signal(t, syscall.SIGKILL)
219			first.waitExit(t, -1)
220			waitTCPPortClosed(t, first.addr)
221	
222			path := filepath.Join(dataDir, "incidents.log")
223			// Both frames are complete and sequentially numbered as if the
224			// no-op handover had committed; recovery must abort at the handover
225			// rather than skip it and apply the following note.
226			bad := incidents.NewActionRecord(incidents.Request{
227				IncidentID: "INC-8", ActionID: "o1", Operator: "alice",
228				ExpectedVersion: 3, Type: incidents.ActionAssignOwner, Content: "bob",
229			}, stamp(2))
230			follow := incidents.NewActionRecord(incidents.Request{
231				IncidentID: "INC-8", ActionID: "n1", Operator: "alice",
232				ExpectedVersion: 4, Type: incidents.ActionNote, Content: "after the bad handover",
233			}, stamp(3))
234			wantBytes := appendFrames(t, path, bad, follow)
235	
236			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
237				"recover incidents", "itself", `"bob"`)
238		})
239	}
240	
241	// TestServeIllegalHandoverBeforeTornTailKeepsEveryByte covers the recovery
242	// ordering regression: a complete illegal handover record followed by an
243	// unfinished trailing write. Startup must reject the handover and leave the
244	// log byte-for-byte intact — the torn tail must not be trimmed before the
245	// failure, and no complete record may be rewritten or dropped. Both torn
246	// shapes are covered: a partial frame header, and a full header whose
247	// payload never completely landed.
248	func TestServeIllegalHandoverBeforeTornTailKeepsEveryByte(t *testing.T) {
249		stamp := func(sec int) time.Time {
250			return time.Date(2026, 10, 1, 12, 0, 0, sec, time.UTC)
251		}
252		frame := func(t *testing.T, record incidents.Record) []byte {
253			t.Helper()
254			payload, err := incidents.MarshalRecord(record)
255			if err != nil {
256				t.Fatal(err)
257			}
258			out := make([]byte, 8+len(payload))
259			binary.BigEndian.PutUint32(out[0:4], uint32(len(payload)))
260			binary.BigEndian.PutUint32(out[4:8], crc32.ChecksumIEEE(payload))
261			copy(out[8:], payload)
262			return out
263		}
264		// seed writes one legal incident through the live server and hard kills
265		// it, returning the incident log path and its confirmed bytes.
266		seed := func(t *testing.T, assignBob bool) (string, string) {
267			t.Helper()
268			dataDir := t.TempDir()
269			first := startServer(t, dataDir)
270			postIncident(t, first, `{"id":"INC-9","title":"t","service":"gateway","operator":"Alice"}`)
271			if assignBob {
272				if s, _ := postIncidentAction(t, first, "INC-9",
273					`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
274					t.Fatalf("add bob status %d", s)
275				}
276			}
277			first.signal(t, syscall.SIGKILL)
278			first.waitExit(t, -1)
279			waitTCPPortClosed(t, first.addr)
280			return dataDir, filepath.Join(dataDir, "incidents.log")
281		}
282	
283		t.Run("non-participant handover ahead of a partial header", func(t *testing.T) {
284			dataDir, path := seed(t, true)
285	
286			bad := incidents.NewActionRecord(incidents.Request{
287				IncidentID: "INC-9", ActionID: "o1", Operator: "alice",
288				ExpectedVersion: 2, Type: incidents.ActionAssignOwner, Content: "carol",
289			}, stamp(1))
290			existing, err := os.ReadFile(path)
291			if err != nil {
292				t.Fatal(err)
293			}
294			// The tail is only the first three bytes of the next frame's header.
295			torn := frame(t, incidents.NewActionRecord(incidents.Request{
296				IncidentID: "INC-9", ActionID: "n1", Operator: "alice",
297				ExpectedVersion: 3, Type: incidents.ActionNote, Content: "never finished",
298			}, stamp(2)))[:3]
299			wantBytes := append(append(append([]byte{}, existing...), frame(t, bad)...), torn...)
300			if err := os.WriteFile(path, wantBytes, 0o644); err != nil {
301				t.Fatal(err)
302			}
303	
304			// The error must name the handover rule and target, not the torn tail.
305			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
306				"recover incidents", "non-participant", `"carol"`)
307			// A retry fails identically: nothing was trimmed or rewritten.
308			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
309				"recover incidents", "non-participant", `"carol"`)
310		})
311	
312		t.Run("self handover ahead of a header-complete torn payload", func(t *testing.T) {
313			dataDir, path := seed(t, false)
314	
315			bad := incidents.NewActionRecord(incidents.Request{
316				IncidentID: "INC-9", ActionID: "o1", Operator: "alice",
317				ExpectedVersion: 1, Type: incidents.ActionAssignOwner, Content: "Alice",
318			}, stamp(1))
319			existing, err := os.ReadFile(path)
320			if err != nil {
321				t.Fatal(err)
322			}
323			// The tail has a complete header but only half of its payload.
324			tornFrame := frame(t, incidents.NewActionRecord(incidents.Request{
325				IncidentID: "INC-9", ActionID: "n1", Operator: "alice",
326				ExpectedVersion: 2, Type: incidents.ActionNote, Content: "never finished",
327			}, stamp(2)))
328			torn := tornFrame[:8+(len(tornFrame)-8)/2]
329			wantBytes := append(append(append([]byte{}, existing...), frame(t, bad)...), torn...)
330			if err := os.WriteFile(path, wantBytes, 0o644); err != nil {
331				t.Fatal(err)
332			}
333	
334			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
335				"recover incidents", "itself", `"Alice"`)
336		})
337	}
338	
339	// TestServeLegalIncidentHistoryWithTornTailStarts confirms the torn-tail
340	// rule still applies when every complete record is legal: startup trims only
341	// the unfinished trailing write, and the incident recovers to the last
342	// complete record's state — owner, participants, version, and history
343	// unchanged, with the tail neither applied nor fabricated into history.
344	func TestServeLegalIncidentHistoryWithTornTailStarts(t *testing.T) {
345		dataDir := t.TempDir()
346		first := startServer(t, dataDir)
347		postIncident(t, first, `{"id":"INC-10","title":"t","service":"gateway","operator":"Alice"}`)
348		if s, _ := postIncidentAction(t, first, "INC-10",
349			`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
350			t.Fatalf("add bob status %d", s)
351		}
352		if s, _ := postIncidentAction(t, first, "INC-10",
353			`{"action_id":"o1","operator":"alice","expected_version":2,"action":"assign_owner","participant":"bob"}`); s != http.StatusOK {
354			t.Fatalf("assign bob status %d", s)
355		}
356		first.signal(t, syscall.SIGKILL)
357		first.waitExit(t, -1)
358		waitTCPPortClosed(t, first.addr)
359	
360		path := filepath.Join(dataDir, "incidents.log")
361		complete, err := os.ReadFile(path)
362		if err != nil {
363			t.Fatal(err)
364		}
365		// A torn tail: a full header plus only part of an assign_owner payload.
366		tornRecord := incidents.NewActionRecord(incidents.Request{
367			IncidentID: "INC-10", ActionID: "o2", Operator: "alice",
368			ExpectedVersion: 3, Type: incidents.ActionAssignOwner, Content: "Alice",
369		}, time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC))
370		tornPayload, err := incidents.MarshalRecord(tornRecord)
371		if err != nil {
372			t.Fatal(err)
373		}
374		torn := make([]byte, 8+6)
375		binary.BigEndian.PutUint32(torn[0:4], uint32(len(tornPayload)))
376		binary.BigEndian.PutUint32(torn[4:8], crc32.ChecksumIEEE(tornPayload))
377		copy(torn[8:], tornPayload[:6])
378		if err := os.WriteFile(path, append(append([]byte{}, complete...), torn...), 0o644); err != nil {
379			t.Fatal(err)
380		}
381	
382		second := startServer(t, dataDir)
383		status, got := getIncident(t, second, "INC-10")
384		if status != http.StatusOK {
385			t.Fatalf("get after torn-tail restart %d", status)
386		}
387		if got["owner"] != "bob" || got["status"] != "open" || incNumber(got["version"]) != 3 {
388			t.Fatalf("recovered head must match the last complete record: %v", got)
389		}
390		members, _ := got["participants"].([]any)
391		if len(members) != 2 || members[0] != "Alice" || members[1] != "bob" {
392			t.Fatalf("recovered participants: %v", got["participants"])
393		}
394		history, _ := got["history"].([]any)
395		if len(history) != 3 {
396			t.Fatalf("the torn tail must not become a history entry: %v", got["history"])
397		}
398		last := history[2].(map[string]any)
399		if last["action"] != "assign_owner" || last["action_id"] != "o1" || incNumber(last["version"]) != 3 {
400			t.Fatalf("last history entry: %v", last)
401		}
402	
403		// Only the torn bytes were dropped; every complete record is untouched.
404		trimmed, err := os.ReadFile(path)
405		if err != nil {
406			t.Fatal(err)
407		}
408		if !bytes.Equal(trimmed, complete) {
409			t.Fatal("startup must trim exactly the torn tail and keep every complete record")
410		}
411	
412		// The action the torn write hinted at never happened: Alice is not the
413		// owner, and a fresh handover to Alice commits as version 4.
414		if s, r := postIncidentAction(t, second, "INC-10",
415			`{"action_id":"o2","operator":"alice","expected_version":3,"action":"assign_owner","participant":"Alice"}`); s != http.StatusOK || incNumber(r["version"]) != 4 {
416			t.Fatalf("handover after trim %d %v", s, r)
417		}
418		second.signal(t, syscall.SIGTERM)
419		second.waitExit(t, 0)
420	}
421	
422	// expectServeFailsOnIncidentLog runs serve against dataDir, requires a
423	// non-zero exit without a readiness line, checks that the startup error
424	// contains every want fragment, and verifies the incident log file is
425	// byte-for-byte unchanged.
426	func expectServeFailsOnIncidentLog(t *testing.T, dataDir string, wantBytes []byte, path string, want ...string) {
427		t.Helper()
428		logs := &safeBuffer{}
429		proc := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
430		proc.Stdout = logs
431		proc.Stderr = logs
432		if err := proc.Start(); err != nil {
433			t.Fatal(err)
434		}
435		done := make(chan error, 1)
436		go func() { done <- proc.Wait() }()
437		ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
438		defer cancel()
439		select {
440		case err := <-done:
441			if err == nil {
442				t.Fatal("an illegal handover record must prevent startup")
443			}
444			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
445				t.Fatalf("startup must exit non-zero: %v", err)
446			}
447		case <-ctx.Done():
448			proc.Process.Kill()
449			t.Fatalf("server stayed up despite an illegal handover record; output:\n%s", logs.String())
450		}
451	
452		out := logs.String()
453		for _, fragment := range want {
454			if !strings.Contains(out, fragment) {
455				t.Fatalf("startup error must contain %q:\n%s", fragment, out)
456			}
457		}
458		if strings.Contains(out, "listening on") {
459			t.Fatalf("failed startup must not announce readiness:\n%s", out)
460		}
461	
462		after, err := os.ReadFile(path)
463		if err != nil {
464			t.Fatal(err)
465		}
466		if !bytes.Equal(after, wantBytes) {
467			t.Fatal("failed startup must not modify the incident log, complete offending frame included")
468		}
469	}
