16		"path/filepath"
17		"strings"
18		"sync"
19		"syscall"
20		"testing"
21		"time"
22	)
23	
24	var (
25		binaryPath string
26		buildOnce  sync.Once
27		buildErr   error
28	)
29	
30	func TestMain(m *testing.M) {
31		buildOnce.Do(func() {
32			dir, err := os.MkdirTemp("", "signalroom-build-")
33			if err != nil {
34				buildErr = err
35				return
36			}
37			binaryPath = filepath.Join(dir, "signalroom")
38			buildErr = exec.Command("go", "build", "-o", binaryPath, ".").Run()
39		})
40		if buildErr != nil {
41			fmt.Fprintln(os.Stderr, "build test binary:", buildErr)
42			os.Exit(1)
43		}
44		os.Exit(m.Run())
45	}
46	
47	type serverProc struct {
48		cmd    *exec.Cmd
49		addr   string
50		logs   *safeBuffer
51		waitCh chan error
52		done   chan struct{}
53	}
54	
55	func (p *serverProc) exited() bool {
56		select {
57		case <-p.done:
58			return true
59		default:
60			return false
61		}
62	}
63	
64	type safeBuffer struct {
65		mu  sync.Mutex
66		buf bytes.Buffer
67	}
68	
69	func (s *safeBuffer) Write(p []byte) (int, error) {
70		s.mu.Lock()
71		defer s.mu.Unlock()
72		return s.buf.Write(p)
73	}
74	
75	func (s *safeBuffer) String() string {
76		s.mu.Lock()
77		defer s.mu.Unlock()
78		return s.buf.String()
79	}
80	
81	// startServer launches serve on an ephemeral port and blocks until the
82	// readiness line publishes the real address — no fixed sleeps.
83	func startServer(t *testing.T, dataDir string) *serverProc {
84		t.Helper()
85		logs := &safeBuffer{}
86		cmd := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
87		stdout, err := cmd.StdoutPipe()
88		if err != nil {
89			t.Fatal(err)
90		}
91		stderr, err := cmd.StderrPipe()
92		if err != nil {
93			t.Fatal(err)
94		}
95		if err := cmd.Start(); err != nil {
96			t.Fatalf("start serve: %v", err)
97		}
98		waitCh := make(chan error, 1)
99		done := make(chan struct{})
100		go func() {
101			waitCh <- cmd.Wait()
102			close(done)
103		}()
104	
105		ready := make(chan string, 1)
106		scan := func(r io.Reader) {
107			scanner := bufio.NewScanner(r)
108			for scanner.Scan() {
109				line := scanner.Text()
110				logs.Write([]byte(line + "\n"))
111				if addr, ok := strings.CutPrefix(line, "signalroom: listening on "); ok {
112					select {
113					case ready <- strings.TrimSpace(addr):
114					default:
115					}
116				}
117			}
118		}
119		go scan(stdout)
120		go scan(stderr)
121	
122		select {
123		case addr := <-ready:
124			proc := &serverProc{cmd: cmd, addr: addr, logs: logs, waitCh: waitCh, done: done}
125			t.Cleanup(func() { proc.killIfAlive() })
126			return proc
127		case err := <-waitCh:
128			t.Fatalf("serve exited before becoming ready (%v); output:\n%s", err, logs.String())
129			return nil
130		case <-time.After(5 * time.Second):
131			t.Fatalf("server never became ready; output:\n%s", logs.String())
132			return nil
133		}
134	}
135	
136	func (p *serverProc) signal(t *testing.T, sig os.Signal) {
137		t.Helper()
138		if err := p.cmd.Process.Signal(sig); err != nil {
139			t.Fatalf("signal: %v", err)
140		}
141	}
142	
143	func (p *serverProc) waitExit(t *testing.T, wantCode int) {
144		t.Helper()
145		select {
146		case err := <-p.waitCh:
147			_ = err // captured below via ProcessState
148		case <-time.After(5 * time.Second):
149			t.Fatalf("process did not exit; output:\n%s", p.logs.String())
150		}
151		state := p.cmd.ProcessState
152		if state == nil {
153			t.Fatal("process state unavailable after wait")
154		}
155		got := state.ExitCode()
156		if got != wantCode {
157			t.Fatalf("want exit %d, got %d; output:\n%s", wantCode, got, p.logs.String())
158		}
159	}
160	
161	func (p *serverProc) killIfAlive() {
162		if p.exited() {
163			return
164		}
165		_ = p.cmd.Process.Signal(syscall.SIGKILL)
166		<-p.done
167	}
168	
169	func httpDo(t *testing.T, method, url, body string) (int, []byte) {
170		t.Helper()
171		var reader io.Reader
172		if body != "" {
173			reader = strings.NewReader(body)
174		}
175		req, err := http.NewRequest(method, url, reader)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if body != "" {
180			req.Header.Set("Content-Type", "application/json")
181		}
182		resp, err := http.DefaultClient.Do(req)
183		if err != nil {
184			t.Fatalf("%s %s: %v", method, url, err)
185		}
186		defer resp.Body.Close()
187		raw, err := io.ReadAll(resp.Body)
188		if err != nil {
189			t.Fatal(err)
190		}
191		return resp.StatusCode, raw
192	}
193	
194	func postEvents(t *testing.T, p *serverProc, body string) map[string]int {
195		t.Helper()
196		status, raw := httpDo(t, http.MethodPost, "http://"+p.addr+"/events", body)
197		if status >= 400 {
198			t.Fatalf("POST status %d: %s", status, raw)
199		}
200		var out map[string]int
201		if err := json.Unmarshal(raw, &out); err != nil {
202			t.Fatal(err)
203		}
204		return out
205	}
206	
207	func getEvents(t *testing.T, p *serverProc, query string) []map[string]any {
208		t.Helper()
209		status, raw := httpDo(t, http.MethodGet, "http://"+p.addr+"/events"+query, "")
210		if status != http.StatusOK {
211			t.Fatalf("GET status %d: %s", status, raw)
212		}
213		var out []map[string]any
214		if err := json.Unmarshal(raw, &out); err != nil {
215			t.Fatalf("decode %q: %v", raw, err)
216		}
217		return out
218	}
219	
220	func waitTCPPortClosed(t *testing.T, addr string) {
221		t.Helper()
222		deadline := time.Now().Add(5 * time.Second)
223		for time.Now().Before(deadline) {
224			conn, err := net.DialTimeout("tcp", addr, 100*time.Millisecond)
225			if err != nil {
226				return
227			}
228			conn.Close()
229			time.Sleep(2 * time.Millisecond)
230		}
