725		}
726		if len(out.Events) != 1 || out.Events[0]["id"] != "e2" {
727			t.Fatalf("legacy dir second page: %v", out.Events)
728		}
729		p.signal(t, syscall.SIGTERM)
730		p.waitExit(t, 0)
731	}
732	
733	func TestServePreviewStableAcrossRestart(t *testing.T) {
734		dataDir := t.TempDir()
735		p := startServer(t, dataDir)
736		postEvents(t, p, `{"events":[
737			{"id":"e1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:00:05Z","labels":{"env":"prod"}},
738			{"id":"e2","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:01:05Z","labels":{"env":"prod"}},
739			{"id":"e3","service":"api","severity":"info","message":"m","at":"2026-10-01T10:00:05Z"}
740		]}`)
741	
742		body := `{"since":"2026-10-01T10:00:00Z","until":"2026-10-01T10:03:00Z",` +
743			`"window_seconds":60,"threshold":1,"trigger_windows":2,"recover_windows":1,` +
744			`"group_labels":["env"]}`
745		_, before := httpDo(t, http.MethodPost, "http://"+p.addr+"/alerts/preview", body)
746	
747		p.signal(t, syscall.SIGKILL)
