118		stop := make(chan os.Signal, 1)
119		signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
120		select {
121		case sig := <-stop:
122			fmt.Fprintf(os.Stderr, "signalroom: received %s, shutting down\n", sig)
123		case err := <-serverErr:
124			if !errors.Is(err, http.ErrServerClosed) {
125				return fmt.Errorf("serve: %w", err)
126			}
127		}
128	
129		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
130		defer cancel()
131		if err := server.Shutdown(shutdownCtx); err != nil {
132			return fmt.Errorf("shutdown: %w", err)
