	reg, _, _ := newTestRegistry(&fakeEvents{})
	_, _ = reg.Create(validCreation())

	base := Request{IncidentID: "INC-1", ActionID: "a", Operator: "alice",
		ExpectedVersion: 1, Type: ActionAddParticipant}
