// overlapRound drives one assign_owner while nReaders detail reads overlap
// its save window. The stall is always released before returning — even when
// the caller later fails — so a failing assertion can never strand the
// blocked server handler and hang server shutdown. early holds responses
// that arrived while the save was still unfinished; late holds the rest.
func overlapRound(t *testing.T, client *http.Client, base, incidentID, handoverBody string, nReaders int) (saved httpResult, early, late []httpResult) {
	t.Helper()

	release, entered := armAndPost(t, client, base, incidentID, handoverBody)
	defer release()
	<-entered

	results := make(chan httpResult, nReaders)
	for i := 0; i < nReaders; i++ {
		go func() {
			results <- doControlledRequest(client, base, http.MethodGet, "/incidents/"+incidentID, "")
		}()
	}

	// Anything that answers while the save is unfinished is an "early" read.
	earlyDeadline := time.After(50 * time.Millisecond)
drainEarly:
	for {
		select {
		case res := <-results:
			early = append(early, res)
		case <-earlyDeadline:
			break drainEarly
		}
	}

	// Finish the save and wait for the handover confirmation.
	release()
	savedOutcome := make(chan httpResult, 1)
	go func() {
		savedOutcome <- doControlledRequest(client, base, http.MethodPost,
			"/incidents/"+incidentID+"/actions", handoverBody)
	}()

	// Drain every remaining reader; the save has completed by the time these
	// are answered, so each snapshot must already be one whole state.
	remaining := nReaders - len(early)
	deadline := time.After(5 * time.Second)
	for len(late) < remaining {
		select {
		case res := <-results:
			late = append(late, res)
		case <-deadline:
			t.Fatalf("only %d of %d overlapping reads returned", len(early)+len(late), nReaders)
		}
	}

	select {
	case saved = <-savedOutcome:
		// This is an idempotent replay of the just-confirmed action: it must
		// return the same result without persisting or advancing anything.
	case <-time.After(5 * time.Second):
		t.Fatal("handover replay after release never returned")
	}
	return saved, early, late
}

// armAndPost arms a one-shot stall and posts handoverBody, returning the
// release func and the "entered" signal.
func armAndPost(t *testing.T, client *http.Client, base, incidentID, handoverBody string) (func(), chan struct{}) {
	t.Helper()
	// Reach into the controlled store through the registry's wiring: the
	// caller passes the store separately, so this helper takes it directly.
	return nil, nil
}

